-- 6. FRAUD ALERTS
SELECT transaction_id,
       'Large Transaction',
       'ATM cash withdrawal of $15,000 at 1:03 AM — amount exceeds 3x account 90-day average.',
       'Critical', '2025-01-22 01:03:45', FALSE
FROM transactions WHERE reference_number = 'REF-001-0105';

SELECT transaction_id,
       'After-Hours Activity',
       'Payment of $4,200 to Unknown Vendor processed at 3:12 AM — unrecognised payee combined with after-hours timing.',
       'High', '2025-02-21 03:12:30', FALSE
FROM transactions WHERE reference_number = 'REF-005-0203';

SELECT transaction_id,
       'After-Hours Activity',
       'ATM withdrawal of $2,800 at 2:48 AM — after-hours large ATM withdrawal significantly above customer average.',
       'Medium', '2025-02-18 02:48:15', FALSE
FROM transactions WHERE reference_number = 'REF-010-0203';

